<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Stop; use Illuminate\Http\Request;
class StopController extends Controller { public function index(Request $r){$stops=Stop::when($r->q,fn($q,$v)=>$q->where('name','like',"%$v%")->orWhere('code','like',"%$v%"))->orderBy('name')->paginate(10)->withQueryString();return view('admin.stops.index',compact('stops'));} public function create(){return view('admin.stops.form',['stop'=>new Stop]);} public function store(Request $r){Stop::create($this->data($r));return redirect()->route('admin.stops.index')->with('success','Halte berhasil ditambahkan.');} public function edit(Stop $stop){return view('admin.stops.form',compact('stop'));} public function update(Request $r,Stop $stop){$stop->update($this->data($r,$stop));return redirect()->route('admin.stops.index')->with('success','Halte diperbarui.');} public function destroy(Stop $stop){$stop->delete();return back()->with('success','Halte dihapus.');} private function data(Request $r,?Stop $stop=null){return $r->validate(['name'=>'required|max:100','code'=>'required|max:30|unique:stops,code,'.($stop?->id),'address'=>'nullable|max:255','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','is_active'=>'boolean'])+['is_active'=>$r->boolean('is_active')];} }
